package com.insight.quantlife.tests;
import android.app.*;import android.os.*;import org.json.*;
/** Disposable emulator only: local synthetic records, no paid AI calls. */
public class TopicInsightsTest extends DocumentEditorTest {
 String prefix="topic-qa-"+System.nanoTime();java.util.List<String> ids=new java.util.ArrayList<>();
 JSONObject make(String suffix,String type,String title,String note,String... tags)throws Exception{JSONObject r=new JSONObject().put("id",prefix+suffix).put("type",type).put("date","2010-02-03").put("title",title).put("note",note).put("durationMinutes",0).put("tags",new JSONArray(tags));if(type.equals("idea")||type.equals("experience"))r.put("occurredAt","2010-02-03T10:00:00");return r;}
 void put(JSONObject r)throws Exception{h.call("saveRecord",new JSONObject().put("record",r).put("allowDuplicate",true));ids.add(r.getString("id"));}
 void reload()throws Exception{runOnMainSync(()->h.activity.finish());h=new MainHost(this);h.open();h.js("AutoWiki.kick=()=>{};AutoWiki.resume=()=>{}");}
 void range()throws Exception{click("[data-topic-range='custom']");h.js("document.querySelector('#topic-start').value='2010-02-03';document.querySelector('#topic-start').dispatchEvent(new Event('input'));document.querySelector('#topic-end').value='2010-02-03';document.querySelector('#topic-end').dispatchEvent(new Event('input'));document.querySelector('#topic-dates').requestSubmit()");}
 void fits()throws Exception{check(h.js("document.documentElement.scrollWidth<=innerWidth+1").equals("true"),"No horizontal overflow");check(h.js("[...document.querySelectorAll('.topic-dashboard button,.topic-entry')].filter(e=>e.getBoundingClientRect().width>0).every(e=>e.getBoundingClientRect().height>=47)").equals("true"),"Statistics controls have 48px touch targets");}
 @Override public void onStart(){Bundle result=new Bundle();try{
  if(!Build.HARDWARE.matches("ranchu|goldfish"))throw new Exception("Requires disposable emulator");h=new MainHost(this);h.open();h.js("AutoWiki.kick=()=>{};AutoWiki.resume=()=>{}");
  JSONArray previous=records();for(int i=0;i<previous.length();i++){String id=previous.getJSONObject(i).getString("id");if(id.startsWith("topic-qa-"))h.call("deleteRecord",new JSONObject().put("id",id));}
  JSONObject learning=make("learn","learning","理解检索系统","原始学习正文不能被改写。","人工智能","检索系统").put("durationMinutes",30),empty=make("empty","learning","待分类笔记","尚未添加主题。"),work=make("shift","work","跨夜工作班次"," ","项目执行").put("date","2010-02-02").put("workStart","2010-02-02T23:00:00").put("workEnd","2010-02-03T02:00:00").put("breaks",new JSONArray("[{\"start\":\"2010-02-03T00:30:00\",\"end\":\"2010-02-03T01:00:00\"}]"));
  put(learning);put(empty);put(work);put(make("log","work_note","复盘工作进展","完成项目复盘。","项目复盘"));put(make("idea","idea","一个产品点子","统一交互流程。","产品设计"));put(make("experience","experience","一次沟通感悟","先确认需求。","产品设计"));reload();
  click("[data-page='records']");check(h.js("document.querySelector('[data-record-tab=thoughts]').textContent==='随笔'").equals("true"),"Experience and inspiration consolidated under essays");h.tap("#topic-entry",false);until("!!document.querySelector('.topic-dashboard')");range();
  check(h.js("document.querySelector('.topic-overview').innerText.includes('2')&&document.querySelector('.topic-overview').innerText.includes('30分钟')").equals("true"),"Learning headline counts each record and duration once");check(h.js("document.querySelectorAll('.domain-row').length===2&&!document.querySelector('[data-topic-key]')").equals("true"),"Related tags consolidate into broad domains without fine topic ranking");fits();h.screenshot("topics-learning.png");
  click("[data-domain='AI 与技术']");check(h.js("document.querySelectorAll('.domain-detail [data-record]').length===1").equals("true"),"Domain opens matching raw record list");click(".domain-detail [data-record]");until("!!document.querySelector('#doc-mode')");click("#doc-mode");click("#doc-info");check(h.js("document.querySelectorAll('#doc-tag-selected button').length===2").equals("true"),"Editor preserves editable original topic chips");click("[data-tag-remove='0']");h.js("document.querySelector('[data-meta=tags]').value+='，沟通';document.querySelector('[data-meta=tags]').dispatchEvent(new Event('input'))");check(h.js("document.querySelector('#doc-tag-selected').innerText.includes('沟通')").equals("true"),"Typing a new topic updates chips");h.screenshot("topics-editor-tags.png");click("#doc-meta-done");click("#doc-save");until("document.querySelector('#doc-mode').textContent==='编辑'&&!document.querySelector('#doc-save').disabled");
  JSONObject saved=record(learning.getString("id"));check(saved.getString("note").equals(learning.getString("note")),"Tag-only edit preserves original note");check(saved.getInt("durationMinutes")==30&&saved.getJSONArray("tags").toString().equals("[\"检索系统\",\"沟通\"]"),"Native database stores changed labels without altering duration");close();check(h.js("!!document.querySelector('[data-domain=语言与表达]')").equals("true"),"Provisional domain statistics immediately follow saved tag changes");
  click("[data-domain='待分类']");click(".domain-detail [data-record]");click("#doc-mode");click("#doc-info");check(h.js("document.querySelectorAll('#doc-tag-suggestions button').length>0").equals("true"),"Past labels are available as suggestions");h.js("[...document.querySelectorAll('#doc-tag-suggestions button')].find(b=>b.textContent.includes('检索系统')).click()");check(h.js("document.querySelectorAll('#doc-tag-selected button').length===1").equals("true"),"Selecting existing label fills metadata");click("#doc-meta-done");click("#doc-save");until("document.querySelector('#doc-mode').textContent==='编辑'&&!document.querySelector('#doc-save').disabled");close();check(h.js("!document.querySelector('[data-domain=待分类]')").equals("true"),"Unclassified row disappears when all records are tagged");
  click("[data-record-tab='work']");check(h.js("document.querySelector('.topic-overview').innerText.includes('1小时30分')&&document.querySelector('.topic-overview').innerText.includes('1 个班次')").equals("true"),"Work summary clips cross-day shift and deducts rest exactly once");check(h.js("document.querySelectorAll('[data-topic-sort]').length===0 && document.querySelector('.domain-row strong').textContent==='规划与复盘'").equals("true"),"Work domain chart uses journal counts independently of shift hours");check(h.js("document.querySelector('.evidence-calendar').innerText.includes('每日净工时')").equals("true"),"Net shift time is displayed separately by date");h.screenshot("topics-work.png");
  click("[data-record-tab='thoughts']");check(h.js("document.querySelector('.topic-overview').innerText.includes('2')&&document.querySelectorAll('[data-topic-sort]').length===0").equals("true"),"Essays aggregate both legacy types without invented duration");click("[data-domain='产品与创意']");check(h.js("document.querySelectorAll('.domain-detail [data-record]').length===2").equals("true"),"Both inspiration and experience remain readable");fits();h.screenshot("topics-essays.png");
  h.js("document.querySelector('#topic-start').value='2010-03-01';document.querySelector('#topic-start').dispatchEvent(new Event('input'));document.querySelector('#topic-dates').requestSubmit()");check(h.js("document.querySelector('#toast').textContent.includes('开始不能晚于结束')").equals("true"),"Invalid range is explained while current statistics stay intact");
  click("#topic-entry");check(h.js("!!document.querySelector('#thought-search')&&!document.querySelector('.topic-dashboard')").equals("true"),"Return from statistics restores essays list");
  click("#topic-entry");click("[data-insights-mode=usage]");check(h.js("!!document.querySelector(\".usage-dashboard\") && document.body.innerText.includes(\"本机使用统计\")").equals("true"),"Local usage feedback is integrated into statistics");fits();h.screenshot("usage-feedback.png");check(h.js("!JSON.stringify(UsageTelemetry.summary()).includes(\"原始学习正文\")").equals("true"),"Feedback contains no record body");if(h.js("UsageTelemetry.summary().enabled").equals("false"))click("#usage-enabled");click("#usage-enabled");check(h.js("UsageTelemetry.summary().enabled===false").equals("true"),"User can pause usage collection");click("#usage-copy");until("document.querySelector(\"#toast\").textContent.includes(\"已复制脱敏使用反馈\")");check(records().length()>0,"Usage copy does not alter life records");click("#usage-clear");click("#confirm-ok");until("document.querySelector(\"#toast\").textContent.includes(\"使用数据已清空\")");check(h.js("UsageTelemetry.summary().pages.length===0 && UsageTelemetry.summary().events.length===0").equals("true"),"Clear while paused removes all usage aggregates");click("#usage-enabled");
  for(String id:ids)h.call("deleteRecord",new JSONObject().put("id",id));result.putString("stream","PASS TopicInsightsTest: "+passed+" checks\n");finish(Activity.RESULT_OK,result);
 }catch(Throwable ex){try{if(h!=null)h.screenshot("topics-failure.png");}catch(Exception ignored){}result.putString("stream","FAIL TopicInsightsTest after "+passed+": "+ex+"\n"+android.util.Log.getStackTraceString(ex));finish(Activity.RESULT_CANCELED,result);}}
}
